	private Compiled compile() {
		SailDataset dataset = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
		try {
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			assertThat(source.getClass()).isEqualTo(SailDatasetTripleTermSource.class);
			assertThat(source.getSnapshotEpoch()).as("real committed unmodified source admission").isPresent();
			LmdbEvaluationStatistics statistics = statistics();
			EvaluationStrategy strategy = store.getConnectionEvaluationStrategyFactory()
					.createEvaluationStrategy(
							null, source, statistics, store.getQueryExecutionPolicy());
			assertThat(strategy).isInstanceOf(LmdbEvaluationStrategy.class)
					.isNotInstanceOf(LmdbNativeEvaluationStrategy.class);
			assertThat(strategy.getQueryExecutionPolicy().experimentalQueryOptimizations()).isTrue();
			((LmdbEvaluationStrategy) strategy).setTrackResultSize(true);
			assertThat(statistics.estimatorRuntime().frontierSettings().mode()).isEqualTo(FrontierEstimatorMode.OFF);
			assertThat(statistics.estimatorRuntime().statisticsService() == null
					|| statistics.estimatorRuntime().statisticsService().currentManifest().isEmpty())
							.as("OFF fixture has no mapped generation, not a fabricated population")
							.isTrue();
			TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
			TupleExpr optimized = strategy.optimize(expression, statistics, EmptyBindingSet.getInstance());
			String afterOptimization = describe("after-optimize", optimized, statistics);
			QueryEvaluationStep step = strategy.precompile(optimized);
			// One passive export before admission: no query, probe, rebuild, key mutation or publisher.
			System.err.println("GENERIC_ACTUAL_SOURCE_ADMISSION source=" + source.getClass().getName()
					+ " epoch=" + source.getSnapshotEpoch() + " strategy=" + strategy.getClass().getName()
					+ " policy=" + strategy.getQueryExecutionPolicy() + "\n" + afterOptimization
					+ describe("after-precompile", optimized, statistics));
			assertThat(statistics.feedbackPublicationAllowed()).isTrue();
			assertThat(statistics.requiresPreboundRuntimeFeedback()).isTrue();
			Filter filter = filters(optimized).stream()
					.filter(candidate -> candidate.getRuntimeFeedbackContract() != null
							&& candidate.getRuntimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_FILTER))
					.findFirst()
					.orElseThrow(() -> new AssertionError(
							"actual unmodified OFF/no-generation source must produce a FILTER-only residual contract"));
			RuntimeFeedbackContract contract = filter.getRuntimeFeedbackContract();
			assertThat(contract.admissionFlags()).isEqualTo(RuntimeFeedbackContract.ADMIT_FILTER);
			assertThat(contract.descriptor()).isNotInstanceOf(LmdbLearningFeedbackDescriptor.class)
					.isNotInstanceOf(LmdbPhysicalEventFeedbackDescriptor.class);
			assertThat(contract.semanticKind()).isEqualTo(RuntimeFeedbackContract.SemanticKind.FILTER);
			assertThat(contract.rawPrediction()).isEqualTo(RuntimeFeedbackContract.PredictionVector.UNKNOWN);
			assertThat(contract.appliedPrediction()).isEqualTo(RuntimeFeedbackContract.PredictionVector.UNKNOWN);
			assertThat(contract.rawLogicalCardinality()).isNaN();
			assertThat(contract.appliedLogicalCardinality()).isNaN();
			assertThat(contract.rawDependentPrediction())
					.isEqualTo(RuntimeFeedbackContract.DependentPredictionVector.UNKNOWN);
			assertThat(contract.appliedDependentPrediction())
					.isEqualTo(RuntimeFeedbackContract.DependentPredictionVector.UNKNOWN);
			assertThat(contract.algorithm()).isEqualTo(RuntimeFeedbackContract.Algorithm.UNKNOWN);
			assertThat(contract.access()).isEqualTo(RuntimeFeedbackContract.Access.UNKNOWN);
			assertThat(contract.physicalImplementationId()).isZero();
			assertThat(statistics.shouldTrackCostFeedback(filter))
					.as("actual prebound generic filter feedback is active")
					.isTrue();
			assertThat(FilterSurfaceKey.exact(filter)).isNotNull();
			return new Compiled(dataset, statistics, filter, step, optimized, source, strategy);
		} catch (RuntimeException | Error failure) {
			dataset.close();
			throw failure;
		}
	}

	private LmdbLearnedFilterSelectivity learned() {
		return store.getBackingStore().learnedFilterSelectivity();
	}

	private LmdbEvaluationStatistics statistics() {
		return (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setNativeEvaluationEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		config.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		return config;
	}

	/** Uses the same real entry boundary as the next optimizer; a raw parser tree owns no graph proof. */
	private Filter preparedFilter(Compiled compiled) {
		return preparedFilter(compiled.strategy, compiled.source, compiled.statistics);
	}

	private Filter preparedFilter(EvaluationStrategy strategy, SailDatasetTripleTermSource source,
			LmdbEvaluationStatistics statistics) {
		TupleExpr query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		return new LmdbQueryOptimizerPipeline(strategy, source, statistics).withPreparedQueryEntry(
				query, null, EmptyBindingSet.getInstance(), (prepared, cascades) -> filters(prepared).getFirst());
	}

	private static Filter freshFilter() {
		return filters(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr()).getFirst();
	}

	private static List<Filter> filters(TupleExpr root) {
		List<Filter> filters = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				filters.add(filter);
				super.meet(filter);
			}
		});
		return filters;
	}

	private static void assertLearned(FilterPassEstimate estimate) {
		assertThat(estimate).isNotNull();
		assertThat(estimate.getSource()).isIn(FilterPassEstimate.Source.LEARNED_FILTER,
				FilterPassEstimate.Source.LEARNED_TEMPLATE, FilterPassEstimate.Source.LEARNED_PATTERN);
		assertThat(estimate.getPassRatio()).isCloseTo(0.25d, within(1e-12d));
		assertThat(estimate.getEvidenceCount()).isEqualTo(ROWS);
	}

	private record Compiled(SailDataset dataset, LmdbEvaluationStatistics statistics, Filter filter,
			QueryEvaluationStep step, TupleExpr optimized, SailDatasetTripleTermSource source,
			EvaluationStrategy strategy) implements AutoCloseable {
		@Override
		public void close() {
			dataset.close();
		}
	}

