	private static List<StatementPattern> patterns(TupleExpr root) {
		List<StatementPattern> result = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				result.add(node);
				super.meet(node);
			}
		});
		return result;
	}

	private static String describe(String phase, TupleExpr root, LmdbEvaluationStatistics statistics) {
		var runtime = statistics.estimatorRuntime();
		StringBuilder result = new StringBuilder(phase).append(" mode=")
				.append(runtime.frontierSettings().mode())
				.append(" dataEpoch=")
				.append(runtime.snapshotVersion())
				.append(" publication=")
				.append(statistics.feedbackPublicationAllowed())
				.append(" status=")
				.append(runtime.statisticsService() == null ? "<absent>" : runtime.statisticsService().status())
				.append('\n')
				.append(root)
				.append('\n');
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr) {
					RuntimeFeedbackContract contract = node.getRuntimeFeedbackContract();
					result.append(node.getClass().getName())
							.append(" signature=")
							.append(node.getSignature())
							.append(" flags=")
							.append(contract == null ? "<none>" : contract.admissionFlags())
							.append(" descriptor=")
							.append(contract == null ? "<none>" : contract.descriptor())
							.append(" semantic=")
							.append(contract == null ? "<none>" : contract.semanticKind())
							.append(" epochs=")
							.append(contract == null ? "<none>" : contract.dataEpoch() + "/" + contract.catalogEpoch())
							.append(" strings=")
							.append(node.getStringMetricsPlanned())
							.append(" doubles=")
							.append(node.getDoubleMetricsPlanned())
							.append('\n');
				}
				super.meetNode(node);
			}
		});
		return result.toString();
	}

